use crate::tables::segment_tables::{
    S_EOF_TRANS, S_FIRST_FINAL, S_INDEX_OFFSETS, S_INDICIES, S_KEY_OFFSETS, S_RANGE_LENGTHS,
    S_SINGLE_LENGTHS, S_START, S_TRANS_ACTIONS, S_TRANS_KEYS, S_TRANS_TARGS,
};
use crate::types::segment_type::SegmentType;

/// segment's `ParseError` text.
pub(crate) const PARSE_ERROR: &str = "unicode word segmentation parse error";

/// The first segment `segmentWords` finds: its bytes as a range of the input, its type, and how far it advances.
struct Found {
    start: usize,
    end: usize,
    advance: usize,
    typ: SegmentType,
}

/// What a scanner action decided about the token it matched.
#[derive(Clone, Copy)]
enum Finish {
    Number,
    Word,
    Hangul,
    Ideo,
    None,
}

enum Label {
    Resume,
    EofTrans(usize),
    Again,
    TestEof,
}

/// The segments of `input` as blevesearch/segment's direct `Segmenter` returns them, each with its type, and the
/// error it stopped on.
///
/// Each step runs `SegmentWords(data, atEOF = true)` on the rest of the input's bytes, which returns the first
/// segment only; a step that finds none ends the segmentation. A segment ends after a whole rune; one that would
/// not end on a char boundary ends the segmentation with segment's parse error.
pub(crate) fn word_segments(input: &str) -> (Vec<(&str, SegmentType)>, Option<&'static str>) {
    let mut out = Vec::new();
    let mut start = 0;
    while let Some(rest) = input.as_bytes().get(start..)
        && !rest.is_empty()
    {
        match segment_words(rest) {
            Err(e) => return (out, Some(e)),
            Ok(None) => break,
            Ok(Some(f)) => {
                let Some(text) = input.get(start + f.start..start + f.end) else {
                    return (out, Some(PARSE_ERROR));
                };
                out.push((text, f.typ));
                start += f.advance;
            }
        }
    }
    (out, None)
}

/// segment's `segmentWords(data, 1, true, nil, nil)`: the first segment of `data`.
fn segment_words(data: &[u8]) -> Result<Option<Found>, &'static str> {
    let pe = data.len();
    let eof = pe;
    let mut cs = S_START;
    let mut p: usize = 0;
    let mut registers = Registers::default();

    let mut label = if p == pe {
        Label::TestEof
    } else {
        Label::Resume
    };
    loop {
        match label {
            Label::Resume => {
                // Only an end-of-input transition without a finish moves p past the end, where Go indexes past the
                // data and panics; the scan ends there instead.
                let Some(&c) = data.get(p) else {
                    label = Label::TestEof;
                    continue;
                };
                label = Label::EofTrans(transition(cs, c)?);
            }
            Label::EofTrans(trans) => {
                cs = usize::from(entry(&S_TRANS_TARGS, trans)?);
                // The generated actions also keep the scanner's token end (te) and move p back to it before a
                // finish action; every finish action returns here, as one token is wanted and atEOF is set, so
                // those registers are never read again and are left out.
                if let Some(finish) = registers.act(entry(&S_TRANS_ACTIONS, trans)?, p) {
                    return Ok(Some(finish_token(
                        data,
                        finish,
                        registers.start_pos,
                        registers.end_pos,
                    )));
                }
                label = Label::Again;
            }
            Label::Again => {
                // The state's to-state and from-state actions only reset and set the scanner's token start (ts),
                // which nothing reads.
                p += 1;
                label = if p != pe {
                    Label::Resume
                } else {
                    Label::TestEof
                };
            }
            Label::TestEof => {
                // The only end-of-input action (24) sets startPos, which nothing reads afterwards.
                if p == eof
                    && let Some(trans) = usize::from(entry(&S_EOF_TRANS, cs)?).checked_sub(1)
                {
                    label = Label::EofTrans(trans);
                    continue;
                }
                break;
            }
        }
    }
    if cs < S_FIRST_FINAL {
        return Err(PARSE_ERROR);
    }
    Ok(None)
}

/// The entry `i` of a generated table. The tables are generated together, so every state, key and transition one
/// names is in range of the others; were one not, the scan stops with segment's parse error rather than reading past
/// a table.
fn entry<T: Copy>(table: &[T], i: usize) -> Result<T, &'static str> {
    table.get(i).copied().ok_or(PARSE_ERROR)
}

/// The transition of state `cs` on the byte `c`: the state's single keys are searched first, then its ranges, and
/// past both the state's default transition is taken. Each search halves its span per turn, so it ends within the
/// logarithm of the state's key count. Go's searches keep an inclusive upper bound, which falls below zero past the
/// first key; these keep it one key (one range) higher, exclusive, so it stays unsigned, and probe the keys Go's do.
fn transition(cs: usize, c: u8) -> Result<usize, &'static str> {
    let mut keys = usize::from(entry(&S_KEY_OFFSETS, cs)?);
    let mut trans = usize::from(entry(&S_INDEX_OFFSETS, cs)?);
    let mut matched = false;

    let klen = usize::from(entry(&S_SINGLE_LENGTHS, cs)?);
    if klen > 0 {
        let mut lower = keys;
        let mut upper = keys + klen;
        while upper > lower {
            let mid = lower + ((upper - 1 - lower) >> 1);
            let k = entry(&S_TRANS_KEYS, mid)?;
            if c < k {
                upper = mid;
            } else if c > k {
                lower = mid + 1;
            } else {
                trans += mid - keys;
                matched = true;
                break;
            }
        }
        if !matched {
            keys += klen;
            trans += klen;
        }
    }
    if !matched {
        let range_len = usize::from(entry(&S_RANGE_LENGTHS, cs)?);
        if range_len > 0 {
            let mut lower = keys;
            let mut upper = keys + (range_len << 1);
            while upper > lower {
                let mid = lower + (((upper - 2 - lower) >> 1) & !1);
                if c < entry(&S_TRANS_KEYS, mid)? {
                    upper = mid;
                } else if c > entry(&S_TRANS_KEYS, mid + 1)? {
                    lower = mid + 2;
                } else {
                    trans += (mid - keys) >> 1;
                    matched = true;
                    break;
                }
            }
        }
        if !matched {
            trans += range_len;
        }
    }
    Ok(usize::from(entry(&S_INDICIES, trans)?))
}

/// The registers the scanner's actions write: the token's start and end, and the action of the longest match.
#[derive(Default)]
struct Registers {
    act: i32,
    start_pos: usize,
    end_pos: usize,
}

impl Registers {
    /// Runs the actions of code `code` at `p`, and the finish they decide on, if any.
    fn act(&mut self, code: u8, p: usize) -> Option<Finish> {
        match code {
            0 => None,
            10 | 18 => {
                self.end_pos = p;
                None
            }
            34 | 4 => Some(Finish::Number),
            37 | 12 => Some(Finish::Hangul),
            35 | 7 => Some(Finish::Word),
            39 | 38 | 40 | 17 | 15 | 19 => Some(Finish::Ideo),
            41 | 32 | 36 | 31 | 21 | 8 | 1 => Some(Finish::None),
            3 => match self.act {
                1 => Some(Finish::Number),
                2 => Some(Finish::Hangul),
                3 | 5 => Some(Finish::Ideo),
                4 => Some(Finish::Word),
                7 | 12 | 13 => Some(Finish::None),
                _ => None,
            },
            28 => {
                self.start_pos = p;
                self.end_pos = p;
                None
            }
            33 | 13 => {
                self.end_pos = p;
                Some(Finish::None)
            }
            26 | 27 => {
                self.start_pos = p;
                self.end_pos = p;
                Some(Finish::None)
            }
            a @ (5 | 11 | 16 | 6 | 14 | 20 | 9 | 2) => {
                self.end_pos = p;
                self.act = match a {
                    5 => 1,
                    11 => 2,
                    16 => 3,
                    6 => 4,
                    14 => 5,
                    20 => 7,
                    9 => 12,
                    _ => 13,
                };
                None
            }
            a @ (29 | 30 | 25) => {
                self.start_pos = p;
                self.end_pos = p;
                self.act = match a {
                    29 => 1,
                    30 => 4,
                    _ => 13,
                };
                None
            }
            // Go's switch has no default: a code it does not name does nothing.
            _ => None,
        }
    }
}

/// The finish actions of segment_words.rl with `atEOF` set and one token wanted: the token.
///
/// segment's Hangul, Han, Hiragana, Katakana and non-word actions return no token when the rune after it decodes
/// as an invalid byte, which at the end of the input drops the token and the rest (ledger 18). The input is a
/// `&str`, so no invalid byte follows, and the check is left out.
fn finish_token(data: &[u8], finish: Finish, start: usize, mut end: usize) -> Found {
    let typ = match finish {
        Finish::Number => SegmentType::Number,
        Finish::Word | Finish::Hangul => SegmentType::Letter,
        Finish::Ideo => SegmentType::Ideo,
        Finish::None => {
            let mut last = start;
            // A rune decodes from the rest of the data only; at its end, where Go's loop would not advance, the token
            // ends.
            while last <= end
                && let Some(rest) = data.get(last..).filter(|rest| !rest.is_empty())
            {
                last += first_rune_len(rest);
            }
            end = last - 1;
            SegmentType::None
        }
    };
    found(start, end, typ)
}

fn found(start: usize, end: usize, typ: SegmentType) -> Found {
    Found {
        start,
        end: end + 1,
        advance: end + 1,
        typ,
    }
}

/// The bytes the first character of `rest` takes: a character's length, or 1 for a byte that begins no UTF-8
/// character.
fn first_rune_len(rest: &[u8]) -> usize {
    rest.utf8_chunks()
        .next()
        .and_then(|chunk| chunk.valid().chars().next())
        .map_or(1, char::len_utf8)
}
